package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.type.TypeBindings;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_addPropertyCreator_TriageGen1Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDescription;
    private AnnotatedWithParams creator;

    // Constant used in the method call to verifyNonDup
    private static final int C_PROPS = 0; // Assuming 0 based on context, though actual value may vary

    @Before
    public void setUp() {
        beanDescription = mock(BeanDescription.class);
        creator = mock(AnnotatedWithParams.class);
        // We spy on the collector to bypass/stub verifyNonDup if it performs complex logic 
        // or to ensure we are testing the logic inside addPropertyCreator directly.
        creatorCollector = spy(new CreatorCollector(beanDescription, true));
    }

    @Test
    public void testAddPropertyCreator_SingleProperty() {
        CreatorProperty[] properties = new CreatorProperty[]{
                createMockProperty("prop1", null)
        };

        creatorCollector.addPropertyCreator(creator, true, properties);

        // Verify verifyNonDup was called
        verify(creatorCollector).verifyNonDup(creator, C_PROPS, true);
    }

    @Test
    public void testAddPropertyCreator_MultipleProperties_Success() {
        CreatorProperty[] properties = new CreatorProperty[]{
                createMockProperty("prop1", null),
                createMockProperty("prop2", null),
                createMockProperty("prop3", null)
        };

        creatorCollector.addPropertyCreator(creator, false, properties);

        verify(creatorCollector).verifyNonDup(creator, C_PROPS, false);
    }

    @Test
    public void testAddPropertyCreator_DuplicateNames_ThrowsException() {
        CreatorProperty[] properties = new CreatorProperty[]{
                createMockProperty("dup", null),
                createMockProperty("other", null),
                createMockProperty("dup", null) // Duplicate name
        };

        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"dup\""));
        }
    }

    @Test
    public void testAddPropertyCreator_InjectableWithNoName_IsSkipped() {
        // When name is empty AND injectableValueId is NOT null, it should be skipped (not trigger duplicate check)
        CreatorProperty injectable = createMockProperty("", "injectableId");
        CreatorProperty duplicateName = createMockProperty("", null); 

        // If the first one is skipped, the second one (empty name) will be the first one added to the map.
        // To test the skip logic specifically:
        CreatorProperty[] properties = new CreatorProperty[]{
                injectable, // name="", id="id" -> skip
                createMockProperty("valid", null)
        };

        creatorCollector.addPropertyCreator(creator, true, properties);
        // Should not throw exception
    }

    @Test
    public void testAddPropertyCreator_EmptyPropertiesArray() {
        CreatorProperty[] properties = new CreatorProperty[0];
        creatorCollector.addPropertyCreator(creator, true, properties);
        verify(creatorCollector).verifyNonDup(creator, C_PROPS, true);
    }

    @Test
    public void testAddPropertyCreator_InjectableWithEmptyName_NoId_TriggersDuplicate() {
        // name="", id=null -> This is NOT skipped. It is treated as a property with name "".
        CreatorProperty[] properties = new CreatorProperty[]{
                createMockProperty("", null),
                createMockProperty("", null)
        };

        try {
            creatorCollector.addPropertyCreator(creator, true, properties);
            org.junit.Assert.fail("Expected IllegalArgumentException for duplicate empty names");
        } catch (IllegalArgumentException e) {
            org.junit.Assert.assertTrue(e.getMessage().contains("Duplicate creator property \"\""));
        }
    }

    /**
     * Helper to create mock CreatorProperty
     */
    private CreatorProperty createMockProperty(String name, String injectableId) {
        CreatorProperty prop = mock(CreatorProperty.class);
        when(prop.getName()).thenReturn(name);
        if (injectableId != null) {
            when(prop.getInjectableValueId()).thenReturn(injectableId);
        } else {
            when(prop.getInjectableValueId()).thenReturn(null);
        }
        return prop;
    }
}
